"""Dependency plans and presence checks; model imports occur only in install commands."""
from __future__ import annotations

import argparse
import glob
import json
import os
from pathlib import Path
import subprocess
import sys


def context(config):
    repo = Path(__file__).resolve().parents[2]
    agent = repo / config["agent_dir"]
    peptide = repo / "agents/peptide-agent"
    def local(value, base=agent):
        path = Path(value).expanduser()
        return str(path if path.is_absolute() else base / path)
    peptide_python = local(os.environ.get("PEPTIDE_PYTHON", str(Path(os.environ.get("PEPTIDE_ENV_DIR", str(peptide / ".venv"))) / "bin/python")), peptide)
    models = local(os.environ.get("PEPTIDE_MODEL_DIR", str(peptide / ".peptide-agent/models")), peptide)
    enzyme_data = local(os.environ.get("ENZYME_DATA_DIR", str(Path.home() / ".cache/decoupled-rsi/enzyme")))
    mrna_data = local(os.environ.get("MRNA_DATA_DIR", str(Path.home() / ".cache/decoupled-rsi/mrna")))
    profile = config["profile"]
    data = models if profile == "peptide" else mrna_data if profile == "mrna" else enzyme_data
    python = peptide_python if profile == "peptide" else local(os.environ.get("MRNA_PYTHON", str(Path(data) / "venv/bin/python"))) if profile == "mrna" else local(os.environ.get("ENZYME_PYTHON", str(Path(data) / "env/bin/python")))
    revision = "2fc06364715b967f1860aea9cf38778875588b17"
    shared_qwen = Path(models) / "qwen" / revision
    override = os.environ.get("MRNA_QWEN_DIR" if profile == "mrna" else "ENZYME_QWEN_DIR", "") if profile != "peptide" else ""
    qwen = local(override) if override else str(shared_qwen if shared_qwen.is_dir() or profile == "peptide" else Path(data) / "models/qwen" / revision)
    result = {"repo": str(repo), "agent": str(agent), "peptide_agent": str(peptide), "python": python,
              "peptide_python": peptide_python, "data": data, "models": models, "qwen": qwen,
              "enzyme_data": enzyme_data, "mrna_data": mrna_data}
    result["esmfold"] = local(os.environ.get("MRNA_ESMFOLD_DIR", str(Path(enzyme_data) / "models/esmfold2/45fe8656f5b3ef493c17fcf9abe9a2968902e712")))
    return result


def expand(value, variables):
    return value.format_map(variables)


def presence(component, variables):
    missing = []
    checks = []
    for spec in component.get("required_paths", []):
        patterns = spec.get("any_of") or [spec.get("path") or spec["glob"]]
        paths = [expand(p, variables) for p in patterns]
        matches = sorted(set(p for pattern in paths for p in glob.glob(pattern)))
        kind = spec.get("kind", "file")
        valid = []
        for name in matches:
            path = Path(name)
            ok = path.is_dir() if kind == "directory" else path.is_file()
            if ok and kind == "executable":
                ok = os.access(path, os.X_OK)
            if ok and kind != "directory":
                ok = path.stat().st_size >= spec.get("min_bytes", 1)
            if ok:
                valid.append(name)
        ok = len(valid) >= spec.get("min_count", 1)
        checks.append({"paths": paths, "present": ok, "matches": len(valid)})
        if not ok:
            missing.append({"paths": paths, "reason": "required file/directory absent, empty, or incompatible with the declared file shape"})
    for rule in component.get("readiness", []):
        path = expand(rule["path"], variables)
        try:
            value = json.loads(Path(path).read_text())
            for key in rule["key"]:
                value = value[key]
            ok = value == rule["equals"] and type(value) is type(rule["equals"])
        except (OSError, ValueError, KeyError, TypeError):
            ok = False
        checks.append({"path": path, "record_field": rule["key"], "present": ok})
        if not ok:
            missing.append({"path": path, "reason": "required local readiness evidence absent or not passed; no record is generated by this installer"})
    if component.get("manual_reason"):
        missing.append({"reason": component["manual_reason"]})
    return {"id": component["id"], "status": "missing" if missing else "present_unvalidated",
            "checks": checks, "missing": missing,
            "scope": "File-presence and declared-record check only; no model import, inference, license grant, or scientific readiness certification."}


def plan(component, components, variables):
    target = components[component.get("install_via", component["id"])]
    return {**component, "resolved_install_stage": target["id"],
            "stage_includes": target.get("includes", [target["id"]]),
            "resolved_commands": [[expand(part, variables) for part in cmd] for cmd in target.get("install_commands", [])],
            "working_directory": variables["agent"], "presence": presence(component, variables)}


def main():
    parser = argparse.ArgumentParser(description="Inspect dependencies without downloads, or explicitly install one component/stage.")
    parser.add_argument("action", choices=["plan", "check", "install"])
    parser.add_argument("component", nargs="?", default="all")
    if sys.argv[1:] == ["help"]:
        parser.print_help()
        return 0
    args = parser.parse_args()
    config = json.loads(Path(__file__).with_name("dependencies.json").read_text())
    components = {item["id"]: item for item in config["components"]}
    variables = context(config)
    if args.component != "all" and args.component not in components:
        parser.error("unknown component; use plan to list the declared inventory")
    if args.action == "install" and args.component == "all":
        parser.error("install requires an explicit component or stage; there is no implicit all installation")
    chosen = list(components.values()) if args.component == "all" else [components[args.component]]
    if args.action == "plan":
        print(json.dumps({"profile": config["profile"], "components": [plan(c, components, variables) for c in chosen]}, indent=2))
        return 0
    if args.action == "check":
        rows = [presence(c, variables) for c in chosen]
        print(json.dumps({"profile": config["profile"], "components": rows}, indent=2))
        return 2 if any(r["status"] == "missing" for r in rows) else 0
    requested = chosen[0]
    target = components[requested.get("install_via", requested["id"])]
    if requested.get("manual_reason") or target.get("manual_reason"):
        print(json.dumps(presence(requested, variables), indent=2))
        return 2
    commands = target.get("install_commands", [])
    if not commands:
        print(json.dumps({"id": requested["id"], "status": "missing", "reason": "No automatic installation command is defined."}, indent=2))
        return 2
    prerequisites = [presence(components[name], variables) for name in target.get("requires", [])]
    if any(row["status"] == "missing" for row in prerequisites):
        print(json.dumps({"id": requested["id"], "status": "missing", "prerequisites": prerequisites}, indent=2))
        return 2
    for name in target.get("required_environment", []):
        if not os.environ.get(name):
            print(json.dumps({"id": requested["id"], "status": "missing", "reason": "Set " + name + " before installing this stage."}, indent=2))
            return 2
    print(json.dumps({"requested": requested["id"], "installing_stage": target["id"], "includes": target.get("includes", [target["id"]])}), flush=True)
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1", PEPTIDE_PYTHON=variables["peptide_python"],
               PEPTIDE_MODEL_DIR=variables["models"], MRNA_DATA_DIR=variables["mrna_data"], ENZYME_DATA_DIR=variables["enzyme_data"])
    for command in commands:
        argv = [expand(part, variables) for part in command]
        try:
            subprocess.run(argv, cwd=variables["agent"], env=env, check=True)
        except (OSError, subprocess.CalledProcessError) as exc:
            print(json.dumps({"id": requested["id"], "status": "missing", "reason": str(exc)}, indent=2))
            return 2
    result = presence(requested, variables)
    print(json.dumps(result, indent=2))
    return 2 if result["status"] == "missing" else 0


if __name__ == "__main__":
    raise SystemExit(main())
